function dodge(){const e=A.engine,p=e?.player;if(!isLandscape()||!e?.started||e.transition||A.paused||A.menu||p.dodgeCool>0)return;const dir=Math.hypot(p.move.x,p.move.y)>.1?p.move:p.aimDir||{x:1,y:0};const len=Math.hypot(dir.x,dir.y)||1;p.dodgeDir={x:dir.x/len,y:dir.y/len};p.dodgeUntil=e.elapsed+.24;p.dodgeCool=2.2;p.inv=Math.max(p.inv,.35);fx(170,.08,.022,'triangle')}
