function jaxonsMessageHtml(){return `<div class="zs52-menu-layer"><div class="zs52-menu-box" style="text-align:center;"><header><div style="padding:20px;"><span class="kicker">SPECIAL MESSAGE</span><h2>VIP Access</h2></div><button id="zs52JaxonsDismiss">${icon('close')}</button></header><div style="padding:20px;font-size:18px;line-height:1.6;"><p style="margin:0;font-size:24px;">🎮 Daddy has granted you all skins and cheats!</p><p style="margin:15px 0 0;font-size:16px;">Good luck, champ! 🚀</p></div><div style="padding:15px;"><button class="btn primary big" id="zs52JaxonsClose" style="width:100%;">Got it!</button><button style="width:100%;margin-top:8px;padding:10px;border:1px solid #999;background:none;color:#ccc;cursor:pointer;border-radius:4px;font-size:14px;" id="zs52JaxonsDontShow">Don't show this again</button></div></div></div>`;}
