function activateMenuRow(row){const nav=A.menuNav;if(!row)return;if(row.kind==='action'){row.run();return}if(row.kind==='toggle'){row.toggle();renderOverlay();return}if(row.kind==='section'){nav.expanded[row.id]=!nav.expanded[row.id];renderOverlay();return}if(row.kind==='nav'){nav.view=row.view;nav.cursor=0;renderOverlay();return}if(row.kind==='back'){nav.view='top';nav.cursor=0;renderOverlay();return}if(row.kind==='skin'){if(isUnlocked(row.id))selectSkin(row.id);renderOverlay();return}if(row.kind==='admincheat'||row.kind==='admintoggle'){if(row.kind==='admintoggle')row.toggle();else CHEAT_CODES[row.id]?.();renderOverlay();return}}
