function bindJoystick(){const base=$('#zs52Joystick'),knob=$('#zs52JoystickKnob');if(!base||!knob)return;const R=34,dead=.28;let active=false;
 const setKnob=(dx,dy)=>{knob.style.transform=`translate(${dx}px,${dy}px)`};
 const move=(clientX,clientY)=>{const rect=base.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2;let dx=clientX-cx,dy=clientY-cy;const dist=Math.hypot(dx,dy)||1;if(dist>R){dx=dx/dist*R;dy=dy/dist*R}setKnob(dx,dy);const nx=dx/R,ny=dy/R;joyFlick(nx,ny);if(A.menu)return;if(isLandscape()){const moveX=Math.abs(nx)>dead?nx:0,moveY=Math.abs(ny)>dead?ny:0;if(A.engine){A.engine.player.move={x:moveX,y:moveY};if(Math.abs(moveX)>dead||Math.abs(moveY)>dead){const mag=Math.hypot(moveX,moveY)||1;A.engine.player.aimDir={x:moveX/mag,y:moveY/mag}}}}else A.engine&&(A.engine.player.move={x:Math.abs(nx)>dead?Math.sign(nx):0,y:0})};
 const on=e=>{e.preventDefault();if(A.paused||A.menu)return;startGameIfNeeded();active=true;base.classList.add('pressed');try{base.setPointerCapture?.(e.pointerId)}catch{}move(e.clientX,e.clientY)};
 const drag=e=>{if(!active)return;e.preventDefault();move(e.clientX,e.clientY)};
 const off=e=>{e?.preventDefault?.();active=false;base.classList.remove('pressed');setKnob(0,0);joyFlickArmed=true;if(A.engine)A.engine.player.move={x:0,y:0}};
 base.addEventListener('pointerdown',on);base.addEventListener('pointermove',drag);base.addEventListener('pointerup',off);base.addEventListener('pointercancel',off);base.addEventListener('lostpointercapture',off)}
function openMenu(){resetInput();A.menu=true;A.paused=true;A.menuNav={view:'top',cursor:0,expanded:{}};stopLoop();renderOverlay()}
function closeMenu(){A.menu=false;A.paused=false;renderOverlay();startLoop()}
function togglePause(){resetInput();A.paused=!A.paused;if(A.paused){stopLoop();pauseAndStore()}renderOverlay();if(!A.paused)startLoop()}

function toggleFlip(){A.prefs.flip=!A.prefs.flip;savePrefs();renderOverlay()}
function toggleMusic(){A.prefs.music=!A.prefs.music;savePrefs();A.prefs.music?startMusic():stopMusic();renderOverlay()}
function cheatSkipToBoss(bossId){const e=A.engine;if(!e||!e.started)return toast('Start a run first.');const order=BOSS_DEFS.filter(b=>b.threshold!=null).sort((a,b)=>a.threshold-b.threshold).map(b=>b.id).concat(BOSS_DEFS.filter(b=>b.threshold==null).map(b=>b.id));const idx=order.indexOf(bossId);if(idx<0)return;for(let i=0;i<idx;i++)e.bossesSeen[order[i]]=true;e.bossesDefeatedCount=Math.min(BOSS_DEFS.length-1,idx);const def=bossDef(bossId);e.score=Math.max(e.score,def?.threshold||e.score);e.zombies=[];e.bullets=[];e.bossProjectiles=[];e.pickups=[];e.waveSpawned=e.waveTarget;e.waveResolved=e.waveTarget;e.cheated=true;e.ticker=`Cheat activated: skipping to ${def?.name||bossId}`}
const CHEAT_CODES={
 'burst':()=>{const e=A.engine;if(e){e.cheats.burst=true;e.cheated=true;setGun('burst')}toast('Cheat activated: BURST gun unlocked.')},
 'fatamy':()=>{cheatSkipToBoss('fatamy');toast('Cheat activated: skipping to Fat Amy.')},
 'dmr82':()=>{const e=A.engine;if(!e)return toast('Start a run first.');e.cheats.dmr=true;e.cheated=true;setGun('dmr');toast('Cheat activated: infinite DMR-82 ammo.')},
 'goldhearts':()=>{const e=A.engine;if(!e)return toast('Start a run first.');e.cheats.tenLives=true;e.cheated=true;e.player.maxLives=10;e.player.lives=10;toast('Cheat activated: 10 lives - 5 of them gold.')},
 'elite':()=>{A.prefs.codeSkins=[...new Set([...(A.prefs.codeSkins||[]),'phantom'])];savePrefs();toast('Cheat activated: Phantom Elite skin unlocked.')}
};
const CHEAT_SEQUENCES=[
 {pattern:['up','up','down','down','left','right','left','right','fire'],action:'goldhearts'},
 {pattern:['left','left','right','right','left','right','fire'],action:'elite'},
 {pattern:['right','right','up','up','grenade'],action:'dmr82'},
 {pattern:['down','down','up','up','fire'],action:'burst'},
 {pattern:['up','down','up','down','grenade'],action:'fatamy'}
];
