function shoot(force){const e=A.engine,p=e?.player;if(!e||!p||e.transition||p.cool>0)return;const w=WEAPONS[p.gun];if(p.gun!=='pistol'&&!e.cheats.dmr&&p.ammo<=0){setGun('pistol');return}
 if(isLandscape()){const target=e.zombies.filter(z=>!z.dead&&z.x>0&&z.x<e.w).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(target){const dx=target.x-p.x,dy=target.y-p.y,dist=Math.hypot(dx,dy)||1;p.aimDir={x:dx/dist,y:dy/dist}}const aimDir=p.aimDir||{x:1,y:0};const spread=p.gun==='burst'?[-1,0,1]:[0];spread.forEach(s=>{const angle=Math.atan2(aimDir.y,aimDir.x)+s*.35;const vx=Math.cos(angle)*w.speed;const vy=Math.sin(angle)*w.speed;e.bullets.push({x:p.x+aimDir.x*34,y:p.y+aimDir.y*34,vx,vy,damage:w.damage,life:1.45,gun:p.gun,color:'#fff'})});p.fireFxUntil=e.elapsed+.10}else{const mk=spread=>({x:p.x+spread*20,y:p.y-25,vx:spread*95,vy:-w.speed,damage:w.damage,life:1.45,gun:p.gun,color:'#fff'});if(p.gun==='burst')e.bullets.push(mk(-1),mk(0),mk(1));else e.bullets.push(mk(0));p.fireFxUntil=e.elapsed+.10}
 p.cool=e.elapsed<e.rapidUntil?Math.max(.055,w.delay*.48):w.delay;if(p.gun!=='pistol'&&!e.cheats.dmr){p.ammo--;if(p.ammo<=0){p.gun='pistol';p.ammo=Infinity}}fx(p.gun==='dmr'?170:p.gun==='smg'?340:p.gun==='burst'?260:280,p.gun==='dmr'?.07:.025)}
function spawnPickup(fromKill=false){const e=A.engine,p=e.player;const early=['speed','shield','heart','heart','heart'];const mid=['clock','speed','shield','rapid','heart','heart'];const late=['clock','bomb','speed','rapid','shield','heart','heart'];let pool=e.infinite?late:(e.wave>=7?late:e.wave>=5?mid:early);if(p.lives<=lowHealthLives(p))pool=[...pool,'heart','heart','heart'];if(Math.random()<.035)pool=[...pool,'goldheart'];const type=pool[Math.floor(Math.random()*pool.length)];e.pickups.push(isLandscape()?{x:e.player.x,y:34+Math.random()*(e.h-68),type,life:fromKill?4.6:6.2,r:15,blink:false}:{x:34+Math.random()*(e.w-68),y:e.player.y,type,life:fromKill?4.6:6.2,r:15,blink:false})}
function spawnBossPickup(e){if(e.pickups.length>=2)return;const p=e.player,z=activeBoss(e);if(z&&Math.random()<.45){spawnKillDrop(z.x+(Math.random()*100-50),z.y+(Math.random()*70-35));return}const low=p.lives<=lowHealthLives(p);let pool=low?['heart','heart','heart','shield','clock']:['heart','heart','shield','clock','rapid'];if(Math.random()<.08)pool=[...pool,'goldheart'];const type=pool[Math.floor(Math.random()*pool.length)];e.pickups.push(isLandscape()?{x:e.player.x,y:34+Math.random()*(e.h-68),type,life:7,r:15,blink:false}:{x:34+Math.random()*(e.w-68),y:e.player.y,type,life:7,r:15,blink:false})}
function applyPickup(x){const e=A.engine,p=e.player;if(x.type==='heart')p.lives=Math.min(p.maxLives,p.lives+1);if(x.type==='goldheart')p.lives=p.maxLives;if(x.type==='clock')e.slowUntil=e.elapsed+6;if(x.type==='speed')e.speedUntil=e.elapsed+7;if(x.type==='rapid')e.rapidUntil=e.elapsed+7;if(x.type==='shield')e.shieldUntil=e.elapsed+7;if(x.type==='bomb'){for(const z of e.zombies){if(!z.dead&&!z.boss)damageZombie(e,z,z.hp)}}if((x.type==='smg'||x.type==='dmr')&&!e.cheats.dmr&&!e.cheats.burst)setGun(x.type);if(x.type==='grenade')p.grenades=Math.min(5,(p.grenades||0)+1);e.ticker={heart:'+1 life',goldheart:'FULL HEALTH RESTORED!',clock:'Slow-time active',bomb:'Bomb cleared the horde — bosses resist it',smg:'SMG equipped!',dmr:'DMR-82 equipped!',grenade:'Grenade collected',speed:'FAST MOVE · 7 seconds',rapid:'RAPID FIRE · 7 seconds',shield:'SHIELD · 7 seconds'}[x.type];if(x.type==='goldheart')fxSeq([[660,0,.06,.05,'sine'],[880,.06,.06,.05,'sine'],[1320,.12,.14,.055,'sine']]);else fxSeq([[988,0,.05,.05,'sine'],[1568,.05,.09,.045,'sine']])}
function setGun(g){const e=A.engine,p=e.player;if(e.cheats.dmr){p.gun='dmr';p.ammo=Infinity;return}if(e.cheats.burst){p.gun='burst';p.ammo=Infinity;return}p.gun=g;p.ammo=WEAPONS[g].ammo}
function currentSprite(z){return ({runner:'runner',helmet:'helmet',armored:'armored',toxic:'toxic',brute:'brute',berserker:'berserker',titan:'titan'})[z.type]||'normal'}
