 const actors=e.zombies.map(z=>({z,y:z.y})).concat([{player:true,y:e.player.y}]);
 actors.sort((a,b)=>a.y-b.y);for(const actor of actors){if(actor.player)drawPlayer(c,e);else drawEnemy(c,e,actor.z)}
 for(const b of e.bullets){if(b.life<=0)continue;c.save();c.translate(b.x,b.y);c.rotate(Math.atan2(b.vy,b.vx)+Math.PI/2);if(!drawFit(c,A.images['bullet_'+b.gun],-5,-14,10,28)){c.fillStyle='#ffe1a1';c.fillRect(-2,-7,4,14)}c.restore()}
