 if(e.mapBanner>0&&e.started&&!e.transition){c.save();c.globalAlpha=Math.min(1,e.mapBanner);c.fillStyle='#0a100de0';c.fillRect(e.w*.2,e.h*.06,e.w*.6,38);c.fillStyle='#edce82';c.font='800 19px Barlow Condensed,sans-serif';c.textAlign='center';c.fillText(isLandscape()?'STREET '+e.wave:MAPS[e.mapIndex].name,e.w/2,e.h*.06+25);c.restore()}
 const boss=activeBoss(e);if(boss&&!e.transition){const bw=Math.min(e.w-30,280),x=(e.w-bw)/2;c.fillStyle='#080d0cf0';c.fillRect(x,8,bw,30);c.fillStyle='#eff1e7';c.font='800 12px Barlow Condensed,sans-serif';c.textAlign='center';c.fillText(boss.bossName+' · STAGE '+bossStage(boss),e.w/2,21);c.fillStyle='#632e25';c.fillRect(x+7,27,bw-14,5);c.fillStyle='#ef9e66';c.fillRect(x+7,27,(bw-14)*Math.max(0,boss.hp/boss.maxHp),5)}
