function drawEnemy(c,e,z){if(z.x < -120||z.x>e.w+120)return;const sizes={normal:[56,70],runner:[54,68],helmet:[60,75],toxic:[62,78],armored:[67,82],berserker:[75,92],brute:[88,108],titan:[108,132]};let [w,h]=sizes[z.type]||sizes.normal;if(z.boss){w*=z.scale||1.3;h*=z.scale||1.3}if(z.minion){w*=.65;h*=.65}shadow(c,z.x,z.y+h*.42,w*.35);c.save();if(z.dead)c.globalAlpha=Math.max(0,(z.death||0)/.2);else if(z.flash)c.globalAlpha=.6;const shake=z.boss&&e.elapsed<(z.shakeUntil||0)?Math.sin(e.elapsed*60)*4:0;const step=z.dead||z.boss?0:Math.sin(e.elapsed*8+(z.zig||0))*1.5;const im=z.minion?A.images.weapon_bodypart:z.boss?bossImage(z):A.images[currentSprite(z)];drawFit(c,im,z.x-w/2+shake,z.y-h/2+step,w,h);c.restore();if(z.hp<z.maxHp&&!z.dead&&!z.boss&&!z.minion){c.fillStyle='#091008';c.fillRect(z.x-18,z.y-h/2-6,36,3);c.fillStyle='#adc989';c.fillRect(z.x-18,z.y-h/2-6,36*z.hp/z.maxHp,3)}if(isLandscape()&&(z.attackWind||0)>.1&&!z.dead){c.strokeStyle='#eab978';c.lineWidth=2;c.beginPath();c.ellipse(z.x,z.y+h*.4,z.r+7,8,0,0,Math.PI*2);c.stroke()}}
