function drawGround(c,e){if(isLandscape()){drawAdventureGround(c,e);return}const map=MAPS[e.mapIndex];if(map.id==='cafe'){drawCafeGround(c,e)}else{const im=ensureImage('map_'+map.id,map.img);if(!(isLandscape()?drawScrollingGround(c,im,e):drawCover(c,im,0,0,e.w,e.h))){c.fillStyle='#25282a';c.fillRect(0,0,e.w,e.h)}}c.fillStyle='rgba(2,4,5,.16)';c.fillRect(0,0,e.w,e.h);const level=Math.min(4,Math.max(0,e.wave<=2?0:e.wave<=4?1:e.wave<=6?2:e.wave<=8?3:4));if(level){const stain=ensureImage('stain_'+level,STAIN_SPRITES[level]);c.save();c.globalAlpha=Math.min(.24,.10+level*.035);drawCover(c,stain,0,0,e.w,e.h);c.restore()}const vignette=c.createRadialGradient(e.w/2,e.h*.5,Math.min(e.w,e.h)*.18,e.w/2,e.h*.5,Math.max(e.w,e.h)*.7);vignette.addColorStop(0,'rgba(0,0,0,0)');vignette.addColorStop(1,'rgba(0,0,0,.34)');c.fillStyle=vignette;c.fillRect(0,0,e.w,e.h)}
